impl Solution {
    pub fn find_length_of_lcis(nums: Vec<i32>) -> i32 {
        if nums.is_empty() {
            return 0;
        }
        let mut max_len: i32 = 1;
        let mut curr_len: i32 = 1;
        for i in 1..nums.len() {
            if nums[i] > nums[i - 1] {
                curr_len += 1;
            } else {
                curr_len = 1;
            }
            if curr_len > max_len {
                max_len = curr_len;
            }
        }
        max_len
    }
}

